&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;&lt;b&gt;Inquisitions&lt;/b&gt;&lt;/td&gt;
        &lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#CLANDESTINITE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Clandestinit&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#DESTIN&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Destin&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#HERESIE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;H&#233;r&#233;sie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#POSSESSION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Possession&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#SEDITION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;S&#233;dition&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#SELE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Z&#232;le&lt;/a&gt;&lt;/td&gt;
    &lt;/tr&gt;
